import subprocess

def concatenate_pdfs(input_files, output_file):
    try:
        subprocess.run(['pdfunite'] + input_files + [output_file], check=True)
        print("PDFs concatenated successfully.")
    except subprocess.CalledProcessError:
        print("An error occurred while concatenating PDFs.")

# Example usage
concatenate_pdfs(['file1.pdf', 'file2.pdf'], 'concatenated.pdf')
